<?php declare(strict_types=1); require_once __DIR__.'/../shared/response.php'; require_once __DIR__.'/../shared/request.php'; methodOnly('POST'); safeApi(function():void{$i=jsonRequest();$email=strtolower(inputString($i,'email',true));$token=inputString($i,'reset_token',true);$password=inputString($i,'password',true);$confirm=inputString($i,'confirm_password',true);if($password!==$confirm||strlen($password)<8||!preg_match('/[A-Z]/',$password)||!preg_match('/[a-z]/',$password)||!preg_match('/\d/',$password)||!preg_match('/[^A-Za-z0-9]/',$password))jsonResponse(false,'Password must be 8+ characters with uppercase, lowercase, number, and special character.',null,[],422);$db=apiDatabase();$q=$db->prepare("SELECT r.id,r.customer_id FROM customer_password_resets r JOIN customers c ON c.id=r.customer_id WHERE c.email=:email AND r.token_hash=:hash AND r.used_at IS NULL AND r.expires_at>NOW() LIMIT 1");$q->execute([':email'=>$email,':hash'=>hash('sha256',$token)]);$r=$q->fetch();if(!$r)jsonResponse(false,'This password reset link is invalid or expired.',null,[],422);$db->beginTransaction();$db->prepare('UPDATE customers SET password_hash=:hash WHERE id=:id')->execute([':hash'=>password_hash($password,PASSWORD_DEFAULT),':id'=>$r['customer_id']]);$db->prepare('UPDATE customer_password_resets SET used_at=NOW() WHERE id=:id')->execute([':id'=>$r['id']]);$db->commit();jsonResponse(true,'Password updated successfully.');});
